<?php/** * Created by PhpStorm. * User: zy * Date: 2020/3/4 * Time: 15:31 */namespace App\Http\Controllers\V1\CategoryTemplate;use App\Exceptions\Error;use App\Http\Controllers\V1\BaseController;use CrsSdk\Shop\CategoryTemplate;use Exception;use Illuminate\Http\Request;use Illuminate\Support\Facades\Log;use Illuminate\Validation\ValidationException;class DetailController extends BaseController{    /**     * @param Request $request     *     * @return array     * @throws ValidationException     */    public function index(Request $request)    {        $input                  = $this->getParams($request);        $input['enterprise_id'] = $this->enterpriseId;        try {            $detail = (new CategoryTemplate())->categoryDetail($input);        } catch (Error $error) {            Log::info('获取分类详情失败', $error->data);            notice(100000, [$error->getMessage()]);        } catch (Exception $e) {            Log::info('获取分类详情失败' . $e->getMessage(), $input);            notice(100000, [$e->getMessage()]);        }        return success($detail);    }    /**     * 验证数据     * @param $request     * @return array     * @throws ValidationException     */    protected function getParams($request)    {        // 验证参数        $rule = [            'id' => 'required|integer',        ];        $messages = [            'id.*' => '分类不存在',        ];        return $this->validate($request, $rule, $messages);    }}